39	#[derive(Debug, Clone, Serialize)]
40	pub struct ProvenanceRecord {
41	    pub id: Option<i64>,
42	    pub session_id: String,
43	    pub timestamp_ms: i64,
44	    pub file_path: String,
45	    pub code_hash: String,
46	    pub model_id: String,
47	    pub model_version: String,
48	    pub contributor_type: ContributorType,
49	    pub start_line: u32,
50	    pub end_line: u32,
51	    pub attestation_sig: String,
