201	    pub fn enrich_model_id(&self, session_id: &str, model_id: &str) -> Result<u64> {
202	        let changes = self.conn.execute(
203	            "UPDATE provenance_records SET model_id = ?1
204	             WHERE session_id = ?2 AND model_id = 'unknown'",
205	            params![model_id, session_id],
206	        )?;
207	        Ok(changes as u64)
208	    }
209	
210	    pub fn save_snapshot(
211	        &self,
212	        session_id: &str,
213	        file_path: &str,
214	        content_hash: &str,
215	        mtime_ns: i64,
216	    ) -> Result<()> {
217	        let now = now_ms();
218	        self.conn.execute(
219	            "INSERT OR REPLACE INTO provenance_snapshots
220	             (session_id, file_path, content_hash, mtime_ns, snapshot_time_ms)
221	             VALUES (?1, ?2, ?3, ?4, ?5)",
222	            params![session_id, file_path, content_hash, mtime_ns, now],
223	        )?;
224	        Ok(())
225	    }
226	
227	    pub fn get_snapshot(
228	        &self,
229	        session_id: &str,
230	        file_path: &str,
231	    ) -> Result<Option<(String, i64)>> {
232	        let result = self.conn.query_row(
233	            "SELECT content_hash, mtime_ns FROM provenance_snapshots
234	             WHERE session_id = ?1 AND file_path = ?2",
235	            params![session_id, file_path],
236	            |row| Ok((row.get(0)?, row.get(1)?)),
237	        );
238	        match result {
239	            Ok(v) => Ok(Some(v)),
240	            Err(rusqlite::Error::QueryReturnedNoRows) => Ok(None),
241	            Err(e) => Err(e.into()),
242	        }
243	    }
244	
245	    pub fn get_all_snapshots(
246	        &self,
247	        session_id: &str,
248	    ) -> Result<HashMap<String, (String, i64)>> {
249	        let mut stmt = self.conn.prepare(
250	            "SELECT file_path, content_hash, mtime_ns FROM provenance_snapshots
251	             WHERE session_id = ?1",
252	        )?;
253	        let mut map = HashMap::new();
254	        let rows = stmt.query_map(params![session_id], |row| {
255	            Ok((
256	                row.get::<_, String>(0)?,
257	                row.get::<_, String>(1)?,
258	                row.get::<_, i64>(2)?,
259	            ))
260	        })?;
261	        for row in rows {
262	            let (path, hash, mtime) = row?;
263	            map.insert(path, (hash, mtime));
264	        }
265	        Ok(map)
266	    }
267	
268	    pub fn cleanup(&self, retention_days: i64) -> Result<u64> {
269	        let cutoff = now_ms() - (retention_days * 86_400_000);
270	        let changes = self.conn.execute(
271	            "DELETE FROM provenance_records WHERE timestamp_ms < ?1",
272	            params![cutoff],
273	        )?;
274	        Ok(changes as u64)
275	    }
276	
277	    pub fn record_count(&self) -> Result<u64> {
278	        let count: i64 = self.conn.query_row(
279	            "SELECT COUNT(*) FROM provenance_records",
280	            [],
281	            |row| row.get(0),
282	        )?;
283	        Ok(count as u64)
284	    }
285	}
