287	pub fn detect_changes(
288	    project_dir: &Path,
289	    session_id: &str,
290	    store: &ProvenanceStore,
291	    keypair: &attestation::KeyPair,
292	) -> Result<Vec<ProvenanceRecord>> {
293	    let snapshots = store
294	        .get_all_snapshots(session_id)
295	        .unwrap_or_default();
296	
297	    if snapshots.is_empty() {
298	        return Ok(vec![]);
299	    }
300	
301	    let now = now_ms();
302	    let developer_id = whoami();
303	    let mut records = Vec::new();
304	
305	    for (rel_path, (old_hash, _old_mtime)) in &snapshots {
306	        let abs_path = project_dir.join(rel_path);
307	        if !abs_path.exists() {
308	            continue;
309	        }
310	
311	        let file_bytes = match std::fs::read(&abs_path) {
312	            Ok(b) => b,
313	            Err(_) => continue,
314	        };
315	
316	        let current_hash = content_hash::hash_content(&file_bytes);
317	
318	        if current_hash == *old_hash {
319	            continue;
320	        }
321	
322	        let line_count = String::from_utf8_lossy(&file_bytes).lines().count() as u32;
323	
324	        let sign_data = format!("{}:{}:{}", rel_path, current_hash, now);
325	        let sig = keypair.sign(sign_data.as_bytes());
326	
327	        let rec = ProvenanceRecord {
328	            id: None,
329	            session_id: session_id.to_string(),
330	            timestamp_ms: now,
331	            file_path: rel_path.clone(),
332	            code_hash: current_hash.clone(),
333	            model_id: "unknown".to_string(),
334	            model_version: String::new(),
335	            contributor_type: ContributorType::Ai,
336	            start_line: 1,
337	            end_line: line_count,
338	            attestation_sig: sig,
339	            developer_id: developer_id.clone(),
340	            prompt_hash: String::new(),
341	            project_dir: project_dir.to_string_lossy().to_string(),
342	        };
343	
344	        records.push(rec);
345	    }
346	
347	    Ok(records)
348	}
