350	pub fn snapshot_files(
351	    project_dir: &Path,
352	    session_id: &str,
353	    store: &ProvenanceStore,
354	    files: &[String],
355	) -> Result<usize> {
356	    let mut count = 0;
357	    for rel_path in files {
358	        let abs_path = project_dir.join(rel_path);
359	        if !abs_path.exists() {
360	            continue;
361	        }
362	        let hash = match content_hash::hash_file(&abs_path) {
363	            Ok(h) => h,
364	            Err(_) => continue,
365	        };
366	        let mtime = crate::util::get_file_mtime_ns(abs_path.to_str().unwrap_or(""))
367	            .unwrap_or(0);
368	        store.save_snapshot(session_id, rel_path, &hash, mtime)?;
369	        count += 1;
370	    }
371	    Ok(count)
372	}
373	
374	fn now_ms() -> i64 {
375	    SystemTime::now()
376	        .duration_since(UNIX_EPOCH)
377	        .unwrap_or_default()
378	        .as_millis() as i64
379	}
