74	    pub fn record_pre(
75	        &self,
76	        tool_name: &str,
77	        tool_input_json: &str,
78	        file_path: Option<&str>,
79	    ) -> Result<i64> {
80	        let now = now_ms();
81	        let input_hash = blake3::hash(tool_input_json.as_bytes())
82	            .to_hex()
83	            .to_string();
84	        self.conn.execute(
85	            "INSERT INTO session_tool_log
86	             (session_id, timestamp_ms, tool_name, tool_input_json, tool_input_hash, file_path)
87	             VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
88	            params![
89	                self.session_id,
90	                now,
91	                tool_name,
92	                tool_input_json,
93	                input_hash,
94	                file_path,
95	            ],
96	        )?;
97	        Ok(self.conn.last_insert_rowid())
98	    }
