119	                    tool_input_hash, file_path, content_hash, token_count, mtime_ns
120	             FROM session_tool_log
121	             WHERE session_id = ?1 AND file_path = ?2 AND content_hash IS NOT NULL
122	             ORDER BY timestamp_ms DESC LIMIT 1",
123	            params![self.session_id, file_path],
124	            |row| {
125	                Ok(SessionEntry {
126	                    id: row.get(0)?,
127	                    session_id: row.get(1)?,
128	                    timestamp_ms: row.get(2)?,
129	                    tool_name: row.get(3)?,
