133	                    content_hash: row.get(7)?,
134	                    token_count: row.get(8)?,
135	                    mtime_ns: row.get(9)?,
136	                })
137	            },
138	        );
139	        match result {
140	            Ok(entry) => Ok(Some(entry)),
141	            Err(rusqlite::Error::QueryReturnedNoRows) => Ok(None),
142	            Err(e) => Err(e.into()),
