261	pub fn extract_file_path(tool_name: &str, tool_input: &serde_json::Value) -> Option<String> {
262	    match tool_name {
263	        "Read" => tool_input
264	            .get("file_path")
265	            .and_then(|v| v.as_str())
266	            .map(|s| s.to_string()),
267	        "Grep" => tool_input
268	            .get("path")
269	            .and_then(|v| v.as_str())
270	            .map(|s| s.to_string()),
271	        "Glob" => tool_input
272	            .get("path")
273	            .and_then(|v| v.as_str())
274	            .map(|s| s.to_string()),
275	        "Bash" => {
276	            let cmd = tool_input.get("command").and_then(|v| v.as_str())?;
277	            let parts: Vec<&str> = cmd.split_whitespace().collect();
278	            if parts.len() >= 2 {
279	                let stem = std::path::Path::new(parts[0])
280	                    .file_stem()
281	                    .and_then(|s| s.to_str())
282	                    .unwrap_or(parts[0]);
283	                if matches!(stem, "cat" | "head" | "tail") {
284	                    return Some(parts[1].to_string());
285	                }
286	            }
287	            None
288	        }
289	        _ => None,
290	    }
291	}
