467	fn to_relative(abs_path: &str, project_dir: &std::path::Path) -> Option<String> {
468	    let p = std::path::Path::new(abs_path);
469	    p.strip_prefix(project_dir)
470	        .ok()
471	        .map(|r| r.to_string_lossy().replace('\\', "/"))
472	}
