474	fn handle_pre_tool_use() -> anyhow::Result<()> {
475	    let input = match read_stdin() {
476	        Ok(s) => s,
477	        Err(e) => {
478	            eprintln!("[codeflow] hook health-check: stdin read failed: {}", e);
479	            println!("{{}}");
480	            return Ok(());
481	        }
482	    };
483	
484	    let parsed: serde_json::Value = match serde_json::from_str(&input) {
485	        Ok(v) => v,
486	        Err(e) => {
487	            eprintln!(
488	                "[codeflow] hook health-check: invalid JSON from Claude Code: {}",
489	                e
490	            );
491	            println!("{{}}");
492	            return Ok(());
493	        }
494	    };
495	
496	    if !parsed.is_object() {
497	        eprintln!(
498	            "[codeflow] hook health-check: expected JSON object, got {}",
499	            parsed
500	        );
501	        println!("{{}}");
502	        return Ok(());
503	    }
504	
505	    let tool_name = match parsed.get("tool_name").and_then(|v| v.as_str()) {
506	        Some(name) => name,
507	        None => {
508	            println!("{{}}");
509	            return Ok(());
510	        }
511	    };
512	
513	    let tool_input = match parsed.get("tool_input") {
514	        Some(v) if v.is_object() => v,
515	        _ => {
516	            println!("{{}}");
517	            return Ok(());
518	        }
519	    };
520	
521	    // Log to session + dedup check (single connection, best-effort)
522	    let session_id = codeflow_core::util::session_id();
523	    let file_path = codeflow_core::session::extract_file_path(tool_name, tool_input);
524	    let session_log = open_session_log(&session_id).ok();
525	
526	    if let Some(ref sl) = session_log {
527	        let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
528	        if let Ok(row_id) =
529	            sl.record_pre(tool_name, &tool_input_str, file_path.as_deref())
530	        {
531	            sl.write_pre_id(tool_name, file_path.as_deref(), row_id);
532	        }
533	    }
534	
535	    if std::env::var("CODEFLOW_PROVENANCE").as_deref() != Ok("0") {
536	        let _ = capture_provenance(&session_id, tool_name, tool_input);
537	    }
538	
539	    if std::env::var("CODEFLOW_BUDGET").as_deref() != Ok("0") {
540	        match check_budget() {
541	            Ok(codeflow_core::budget_policy::Verdict::Block(reason)) => {
542	                let response = serde_json::json!({
543	                    "error": format!("budget_exceeded: {}", reason)
544	                });
545	                println!("{}", serde_json::to_string(&response)?);
546	                return Ok(());
547	            }
548	            Ok(codeflow_core::budget_policy::Verdict::Warn(msg)) => {
549	                eprintln!("[codeflow] ⚠ {}", msg);
550	            }
551	            Ok(codeflow_core::budget_policy::Verdict::Allow) => {}
552	            Err(e) => {
553	                eprintln!("[codeflow] budget check error (fail-open): {}", e);
554	            }
555	        }
556	    }
557	
558	    match tool_name {
559	        "Bash" => {
560	            if let Some(command) = tool_input.get("command").and_then(|c| c.as_str()) {
561	                if should_wrap(command) {
562	                    let codeflow_bin = std::env::current_exe()
563	                        .map(|p| p.to_string_lossy().to_string())
564	                        .unwrap_or_else(|_| "codeflow".to_string());
565	                    let quoted_bin = shell_quote(&codeflow_bin);
566	                    let rewritten = format!("{} wrap {}", quoted_bin, command);
567	                    let response = serde_json::json!({
568	                        "tool_input": {
569	                            "command": rewritten
570	                        }
571	                    });
572	                    println!("{}", serde_json::to_string(&response)?);
573	                    return Ok(());
574	                }
575	            }
576	            println!("{{}}");
577	        }
578	        "Read" | "Grep" | "Glob" => {
579	            if let Some(ref session_log) = session_log {
580	                let window_secs = std::env::var("CODEFLOW_DEDUP_WINDOW_SECS")
581	                    .ok()
582	                    .and_then(|v| v.parse().ok());
583	                let dedup =
584	                    codeflow_core::read_dedup::ReadDedup::new(session_log, window_secs);
585	                let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
586	
587	                let result = match tool_name {
588	                    "Read" => {
589	                        if let Some(fp) = file_path.as_deref() {
590	                            dedup.check_read(fp)
591	                        } else {
592	                            codeflow_core::read_dedup::ReadDedupResult::Miss
593	                        }
594	                    }
595	                    "Grep" => dedup.check_grep(&tool_input_str),
596	                    "Glob" => dedup.check_glob(&tool_input_str),
597	                    _ => codeflow_core::read_dedup::ReadDedupResult::Miss,
598	                };
599	
600	                match result {
601	                    codeflow_core::read_dedup::ReadDedupResult::Hit {
602	                        context_message,
603	                        tokens_saved,
604	                    } => {
605	                        let response = serde_json::json!({
606	                            "additionalContext": context_message
607	                        });
608	                        println!("{}", serde_json::to_string(&response).unwrap_or_default());
609	
610	                        // Track savings
611	                        if tokens_saved > 0 {
612	                            if let Ok(tracking) =
613	                                codeflow_core::tracking::TrackingDb::open(&paths::db_path())
614	                            {
615	                                let _ = tracking.record(
616	                                    &codeflow_core::tracking::TrackingEvent {
617	                                        command: tool_name.to_string(),
618	                                        input_tokens: tokens_saved,
619	                                        output_tokens: 0,
620	                                        tokens_saved,
621	                                        layer:
622	                                            codeflow_core::tracking::SavingsLayer::ReadDedup,
623	                                        project: std::env::current_dir()
624	                                            .unwrap_or_default()
625	                                            .to_string_lossy()
626	                                            .to_string(),
627	                                        session_id: session_id.clone(),
628	                                    },
629	                                );
630	                            }
631	                        }
632	                        return Ok(());
633	                    }
634	                    codeflow_core::read_dedup::ReadDedupResult::Miss => {
635	                        println!("{{}}");
636	                    }
637	                }
638	            } else {
639	                println!("{{}}");
640	            }
641	        }
642	        _ => {
643	            println!("{{}}");
644	        }
645	    }
646	
647	    Ok(())
648	}
