650	fn handle_post_tool_use() -> anyhow::Result<()> {
651	    let input = match read_stdin() {
652	        Ok(s) => s,
653	        Err(_) => {
654	            println!("{{}}");
655	            return Ok(());
656	        }
657	    };
658	
659	    let parsed: serde_json::Value = serde_json::from_str(&input).unwrap_or_default();
660	    let tool_name = parsed.get("tool_name").and_then(|v| v.as_str());
661	    let tool_result = parsed
662	        .get("tool_result")
663	        .and_then(|v| v.as_str())
664	        .unwrap_or("");
665	
666	    if let Some(tn) = tool_name {
667	        if matches!(tn, "Read" | "Grep" | "Glob" | "Bash") {
668	            let file_path = parsed
669	                .get("tool_input")
670	                .and_then(|ti| codeflow_core::session::extract_file_path(tn, ti));
671	
672	            let session_id = codeflow_core::util::session_id();
673	            if let Ok(session_log) = open_session_log(&session_id) {
674	                if let Some(row_id) = session_log.take_pre_id(tn, file_path.as_deref()) {
675	                    let capped = if tool_result.len() > 1_048_576 {
676	                        &tool_result[..1_048_576]
677	                    } else {
678	                        tool_result
679	                    };
680	                    let content_hash =
681	                        blake3::hash(capped.as_bytes()).to_hex().to_string();
682	                    let token_count = codeflow_core::util::estimate_tokens(tool_result.len()) as i64;
683	
684	                    let mtime_ns =
685	                        file_path.as_deref().and_then(codeflow_core::util::get_file_mtime_ns);
686	
687	                    let _ = session_log.record_post(
688	                        row_id,
689	                        &content_hash,
690	                        token_count,
691	                        mtime_ns,
692	                    );
693	                }
694	            }
695	        }
696	    }
697	
698	    println!("{{}}");
699	    Ok(())
700	}
