742	fn check_budget() -> anyhow::Result<codeflow_core::budget_policy::Verdict> {
743	    let config = codeflow_core::budget_policy::PolicyConfig::load();
744	    let engine = codeflow_core::budget_policy::PolicyEngine::new(config.clone());
745	    let days = Some(codeflow_core::budget_policy::period_days(&config.global.period));
746	
747	    let db_path = paths::data_dir().join("cost.db");
748	    if !db_path.exists() {
749	        return Ok(codeflow_core::budget_policy::Verdict::Allow);
750	    }
751	
752	    let store = codeflow_core::cost::CostStore::open(&db_path)?;
753	    let developer_id = codeflow_core::util::developer_id();
754	    let project_dir = std::env::current_dir()
755	        .unwrap_or_default()
756	        .to_string_lossy()
757	        .to_string();
758	
759	    let acc_dev = store.accumulated_cost_by_dev(&developer_id, days)?;
760	    let acc_project = store.accumulated_cost(&project_dir, days)?;
761	
762	    Ok(engine.evaluate(&developer_id, &project_dir, acc_dev, acc_project))
763	}
